def split_line(line):
    """Splits one line of comma-separated text into its fields.

    A comma inside double quotes does not split the field, and the quotes are
    dropped. A doubled quote inside a quoted field stands for one quote.
    Spaces around a field are stripped; spaces inside quotes are kept.
    """
    fields = []
    buf = []  # (char, protected) pairs; protected chars came from inside quotes
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if line[i + 1:i + 2] == '"':
                    buf.append(('"', True))
                    i += 1
                else:
                    in_quotes = False
            else:
                buf.append((ch, True))
        elif ch == '"':
            in_quotes = True
        elif ch == ",":
            fields.append(_finish(buf))
            buf = []
        else:
            buf.append((ch, False))
        i += 1
    fields.append(_finish(buf))
    return fields


def _finish(buf):
    start, end = 0, len(buf)
    while start < end and buf[start][0].isspace() and not buf[start][1]:
        start += 1
    while end > start and buf[end - 1][0].isspace() and not buf[end - 1][1]:
        end -= 1
    return "".join(c for c, _ in buf[start:end])

files.tests/test_csvline.py:
from csvline import split_line


def test_plain_fields():
    assert split_line("a,b,c") == ["a", "b", "c"]


def test_strips_spaces():
    assert split_line("a , b") == ["a", "b"]


def test_comma_inside_quotes_stays_in_field():
    assert split_line('a,"b,c",d') == ["a", "b,c", "d"]


def test_address_with_comma():
    assert split_line('Bob,"12 High St, Leeds"') == ["Bob", "12 High St, Leeds"]


def test_doubled_quote_is_one_quote():
    assert split_line('"say ""hi""",x') == ['say "hi"', "x"]


def test_spaces_around_quoted_field_stripped_inside_kept():
    assert split_line(' " a, b " , c') == [" a, b ", "c"]


def test_empty_quoted_field():
    assert split_line('a,"",b') == ["a", "", "b"]

